//! `cargo run --bin replay -- --events tests/fixtures/liquidations.jsonl`
//!
//! Per `docs/TESTING.md#historical-replay` and `docs/RUNBOOK.md#first-action`:
//! "nothing downstream is worth building until it passes." As shipped,
//! this will report zero events and a non-zero exit code, because
//! `tests/fixtures/liquidations.jsonl` doesn't exist yet — see
//! `tests/fixtures/README.md` for why that file is generated by a
//! separate historical-export step rather than checked in, and
//! `crates/sim/src/fixture_schema.rs`'s module doc for why this build
//! environment couldn't run that export step itself.

use clap::Parser;
use gyrfalcon_core::Protocol;
use gyrfalcon_health::{KaminoAdapter, MarginfiAdapter, SaveAdapter};
use gyrfalcon_router::MultiSourceRouter;
use gyrfalcon_sim::{load_events, replay_event, ReplayReport};
use std::path::PathBuf;
use std::process::ExitCode;

#[derive(Parser, Debug)]
#[command(name = "replay", about = "Historical liquidation-event replay harness")]
struct Cli {
    /// Path to tests/fixtures/liquidations.jsonl.
    #[arg(long, default_value = "tests/fixtures/liquidations.jsonl")]
    events: PathBuf,
}

fn main() -> ExitCode {
    let cli = Cli::parse();

    let events = match load_events(&cli.events) {
        Ok(e) => e,
        Err(e) => {
            eprintln!("failed to load {}: {e}", cli.events.display());
            return ExitCode::FAILURE;
        }
    };

    if events.is_empty() {
        eprintln!(
            "no events loaded from {} — this file is generated by a one-time historical \
             export step (see tests/fixtures/README.md), not checked in. Nothing to replay.",
            cli.events.display()
        );
        return ExitCode::FAILURE;
    }

    let mut kamino = KaminoAdapter::new();
    let mut save = SaveAdapter::new();
    let mut marginfi = MarginfiAdapter::new();
    let router = MultiSourceRouter::new();

    let mut results = Vec::with_capacity(events.len());
    for event in &events {
        let res = match event.protocol {
            Protocol::Kamino => replay_event(event, &mut kamino, &router),
            Protocol::Save => replay_event(event, &mut save, &router),
            Protocol::MarginFi => replay_event(event, &mut marginfi, &router),
        };
        results.push(res);
    }
    let report = ReplayReport { results };

    println!(
        "replayed {} events: {} detected, {} routed with sufficient liquidity",
        report.total(),
        report.detected_count(),
        report
            .results
            .iter()
            .filter(|r| r.routed_reserve_had_sufficient_liquidity == Some(true))
            .count(),
    );

    for result in &report.results {
        if !result.detected {
            println!("  MISSED detection: position {}", result.position_id);
        } else if result.routed_reserve_had_sufficient_liquidity != Some(true) {
            println!("  BAD routing: position {}", result.position_id);
        }
    }

    if report.all_detected() && report.all_routed_with_sufficient_liquidity() {
        println!("PASS: all events detected and routed correctly (feasibility not yet checked — see module docs).");
        ExitCode::SUCCESS
    } else {
        println!("FAIL: see per-event failures above.");
        ExitCode::FAILURE
    }
}
